        static String encode(Map<String, Object> map) {
            StringBuilder sb = new StringBuilder();
            writeValue(sb, map);
            return sb.toString();
        }

        private static void writeValue(StringBuilder sb, Object value) {
            if (value == null) {
                sb.append("null");
            } else if (value instanceof String) {
                writeString(sb, (String) value);
            } else if (value instanceof Number || value instanceof Boolean) {
                sb.append(value);
            } else if (value instanceof Map) {
                sb.append('{');
                boolean first = true;
                for (Map.Entry<?, ?> entry : ((Map<?, ?>) value).entrySet()) {
                    if (!first) {
                        sb.append(',');
                    }
                    first = false;
                    writeString(sb, String.valueOf(entry.getKey()));
                    sb.append(':');
                    writeValue(sb, entry.getValue());
                }
                sb.append('}');
            } else if (value instanceof Collection) {
                sb.append('[');
                boolean first = true;
                for (Object element : (Collection<?>) value) {
                    if (!first) {
                        sb.append(',');
                    }
                    first = false;
                    writeValue(sb, element);
                }
                sb.append(']');
            } else {
                throw new IllegalArgumentException("Unsupported JSON value type: " + value.getClass());
            }
        }

        private static void writeString(StringBuilder sb, String text) {
            sb.append('"');
            for (int i = 0; i < text.length(); i++) {
                char c = text.charAt(i);
                switch (c) {
                    case '"': sb.append("\\\""); break;
                    case '\\': sb.append("\\\\"); break;
                    case '\n': sb.append("\\n"); break;
                    case '\r': sb.append("\\r"); break;
                    case '\t': sb.append("\\t"); break;
                    case '\b': sb.append("\\b"); break;
                    case '\f': sb.append("\\f"); break;
                    default:
                        if (c < 0x20) {
                            sb.append(String.format("\\u%04x", (int) c));
                        } else {
                            sb.append(c);
                        }
                }
            }
            sb.append('"');
        }

        static Map<String, Object> decodeObject(String json) {
            Parser parser = new Parser(json);
            parser.skipWs();
            Map<String, Object> result = parser.readObject();
            parser.skipWs();
            if (!parser.eof()) {
                throw new IllegalStateException("Trailing content in JSON input at offset " + parser.pos);
            }
            return result;
        }

        private static final class Parser {
            private final String src;
            int pos;

            Parser(String src) {
                this.src = src;
            }

            boolean eof() {
                return pos >= src.length();
            }

            void skipWs() {
                while (!eof() && Character.isWhitespace(src.charAt(pos))) {
                    pos++;
                }
            }

            char peek() {
                if (eof()) {
                    throw new IllegalStateException("Unexpected end of JSON input");
                }
                return src.charAt(pos);
            }

            void expect(char c) {
                if (peek() != c) {
                    throw new IllegalStateException("Expected '" + c + "' at offset " + pos);
                }
                pos++;
            }

            Map<String, Object> readObject() {
                expect('{');
                Map<String, Object> map = new LinkedHashMap<>();
                skipWs();
                if (peek() == '}') {
                    pos++;
                    return map;
                }
                while (true) {
                    skipWs();
                    String key = readString();
                    skipWs();
                    expect(':');
                    skipWs();
                    map.put(key, readValue());
                    skipWs();
                    char c = peek();
                    pos++;
                    if (c == '}') {
                        return map;
                    }
                    if (c != ',') {
                        throw new IllegalStateException("Expected ',' or '}' at offset " + (pos - 1));
                    }
                }
            }

            List<Object> readArray() {
                expect('[');
                List<Object> list = new ArrayList<>();
                skipWs();
                if (peek() == ']') {
                    pos++;
                    return list;
                }
                while (true) {
                    skipWs();
                    list.add(readValue());
                    skipWs();
                    char c = peek();
                    pos++;
                    if (c == ']') {
                        return list;
                    }
                    if (c != ',') {
                        throw new IllegalStateException("Expected ',' or ']' at offset " + (pos - 1));
                    }
                }
            }

            Object readValue() {
                char c = peek();
                if (c == '{') {
                    return readObject();
                }
                if (c == '[') {
                    return readArray();
                }
                if (c == '"') {
                    return readString();
                }
                if (c == 't') {
                    readLiteral("true");
                    return Boolean.TRUE;
                }
                if (c == 'f') {
                    readLiteral("false");
                    return Boolean.FALSE;
                }
                if (c == 'n') {
                    readLiteral("null");
                    return null;
                }
                return readNumber();
            }

            void readLiteral(String literal) {
                if (!src.startsWith(literal, pos)) {
                    throw new IllegalStateException("Invalid literal at offset " + pos);
                }
                pos += literal.length();
            }

            String readString() {
                expect('"');
                StringBuilder sb = new StringBuilder();
                while (true) {
                    if (eof()) {
                        throw new IllegalStateException("Unterminated string");
                    }
                    char c = src.charAt(pos++);
                    if (c == '"') {
                        return sb.toString();
                    }
                    if (c == '\\') {
                        if (eof()) {
                            throw new IllegalStateException("Unterminated escape sequence");
                        }
                        char escape = src.charAt(pos++);
                        switch (escape) {
                            case '"': sb.append('"'); break;
                            case '\\': sb.append('\\'); break;
                            case '/': sb.append('/'); break;
                            case 'n': sb.append('\n'); break;
                            case 'r': sb.append('\r'); break;
                            case 't': sb.append('\t'); break;
                            case 'b': sb.append('\b'); break;
                            case 'f': sb.append('\f'); break;
                            case 'u':
                                if (pos + 4 > src.length()) {
                                    throw new IllegalStateException("Truncated unicode escape");
                                }
                                sb.append((char) Integer.parseInt(src.substring(pos, pos + 4), 16));
                                pos += 4;
                                break;
                            default:
                                throw new IllegalStateException("Invalid escape sequence \\" + escape);
                        }
                    } else {
                        sb.append(c);
                    }
                }
            }

            Number readNumber() {
                int start = pos;
                while (!eof()) {
                    char c = src.charAt(pos);
                    if (c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' || (c >= '0' && c <= '9')) {
                        pos++;
                    } else {
                        break;
                    }
                }
                String text = src.substring(start, pos);
                if (text.isEmpty()) {
                    throw new IllegalStateException("Invalid number at offset " + start);
                }
                if (text.matches("-?\\d+")) {
                    return Long.parseLong(text);
                }
                return Double.parseDouble(text);
            }
        }
    }
}
