import java.nio.file.Path;
import java.util.List;
import java.util.jar.Attributes;
import java.util.jar.JarEntry;
import java.util.jar.JarOutputStream;
import java.util.jar.Manifest;

public class JarMojo extends AbstractMojo {

    private File classesDirectory;
    private File outputDirectory;
    private String finalName;

    public void execute() throws MojoExecutionException {
        try {
            Files.createDirectories(outputDirectory.toPath());
            File jarFile = new File(outputDirectory, finalName + ".jar");
            Manifest manifest = new Manifest();
            manifest.getMainAttributes().put(Attributes.Name.MANIFEST_VERSION, "1.0");
            manifest.getMainAttributes().putValue("Created-By", "local-stub maven-jar-plugin");
            try (JarOutputStream jos = new JarOutputStream(new FileOutputStream(jarFile), manifest)) {
                if (classesDirectory != null && classesDirectory.isDirectory()) {
                    Path root = classesDirectory.toPath();
                    List<Path> files = Files.walk(root).collect(java.util.stream.Collectors.toList());
                    for (Path path : files) {
                        if (!Files.isRegularFile(path)) {
                            continue;
                        }
                        String name = root.relativize(path).toString().replace(File.separatorChar, '/');
                        jos.putNextEntry(new JarEntry(name));
                        Files.copy(path, jos);
                        jos.closeEntry();
                    }
                }
            }
            getLog().info("Built jar: " + jarFile);
        } catch (IOException | UncheckedIOException e) {
            throw new MojoExecutionException("Failed to build jar: " + e, e);
        }
    }
}
