package stub.maven.plugins;

import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;

import javax.tools.JavaCompiler;
import javax.tools.ToolProvider;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

public class CompilerMojo extends AbstractMojo {

    private File sourceDirectory;
    private File outputDirectory;
    private List classpathElements;
    private String encoding;
    private String release;
    private boolean skipMain;
    private String skip;

    public void execute() throws MojoExecutionException {
        if (skipMain || "true".equals(skip)) {
            return;
        }
        if (sourceDirectory == null || !sourceDirectory.isDirectory()) {
            getLog().info("No sources to compile.");
            return;
        }
        try {
            Files.createDirectories(outputDirectory.toPath());
            List<File> sources = new ArrayList<>();
            for (Path path : Files.walk(sourceDirectory.toPath()).collect(java.util.stream.Collectors.toList())) {
                if (Files.isRegularFile(path) && path.toString().endsWith(".java")) {
                    sources.add(path.toFile());
                }
            }
            if (sources.isEmpty()) {
                getLog().info("No sources to compile.");
                return;
            }
            JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
            if (compiler == null) {
                throw new MojoExecutionException("No system Java compiler available (run on a JDK).");
            }
            List<String> options = new ArrayList<>();
            options.add("-d");
            options.add(outputDirectory.getAbsolutePath());
            options.add("-encoding");
            options.add(encoding != null && !encoding.isEmpty() && !encoding.startsWith("$") ? encoding : "UTF-8");
            if (release != null && !release.isEmpty() && !release.startsWith("$")) {
                options.add("--release");
                options.add(release);
            }
            if (classpathElements != null && !classpathElements.isEmpty()) {
                StringBuilder cp = new StringBuilder();
                for (Object element : classpathElements) {
                    if (cp.length() > 0) {
                        cp.append(File.pathSeparator);
                    }
                    cp.append(element.toString());
                }
                options.add("-classpath");
                options.add(cp.toString());
            }
            List<String> files = new ArrayList<>();
            for (File source : sources) {
                files.add(source.getAbsolutePath());
            }
            int result = compiler.run(null, null, System.err, buildArgs(options, files).toArray(new String[0]));
            if (result != 0) {
                throw new MojoExecutionException("Compilation failure (exit " + result + ")");
            }
            getLog().info("Compiled " + sources.size() + " source file(s) to " + outputDirectory);
        } catch (IOException e) {
            throw new MojoExecutionException("Failed to compile: " + e, e);
        }
    }

    private List<String> buildArgs(List<String> options, List<String> files) {
        List<String> args = new ArrayList<>(options);
        args.addAll(files);
        return args;
    }
}
